export function getMatchingTemplates(niche: string, limit = 2, searchText = ""): ViralTemplate[] {
  const normalizedNiche = niche.toLowerCase().trim();
  const searchLower = searchText.toLowerCase().trim();
  const combinedText = `${normalizedNiche} ${searchLower}`;

  const specialKeywords = [
    "porn", "addiction", "dopamine", "detox", "scrolling", "habit", "discipline", 
    "self-help", "recovery", "semen", "transmutation", "self-mastery", "willpower"
  ];
  
  const matchedKeywords = specialKeywords.filter(kw => combinedText.includes(kw));
  let matches: ViralTemplate[] = [];

  // P1: Keyword matches in the script or topic content
  if (matchedKeywords.length > 0) {
    matches = VIRAL_TEMPLATES.filter(t => {
      const text = `${t.hook} ${t.structure} ${t.keyTakeaway}`.toLowerCase();
      return matchedKeywords.some(kw => text.includes(kw));
    });
  }

  // P2: Niche category matching
  if (matches.length < limit) {
    const nicheMatches = VIRAL_TEMPLATES.filter(
      (t) => (t.niche === normalizedNiche || normalizedNiche.includes(t.niche) || t.niche.includes(normalizedNiche)) && !matches.includes(t)
    );
    matches = [...matches, ...nicheMatches];
  }

  // P3: Fallback to general templates
  if (matches.length < limit) {
    const general = VIRAL_TEMPLATES.filter((t) => t.niche === "general" && !matches.includes(t));
    matches = [...matches, ...general];
  }

  return matches.slice(0, limit);
}
